mapper.select:
SELECT ccb.id, ccb.`name`, ccb.parentId, ccb.type, ccb.creditCode, ccb.orderNum, ccb.clinicNumber, case ccb.type when 0 then '公司' when 1 then '大区' when 2 then ccb.abbreviation else '其他' end as abbreviation, ccb.brandName, ccb.tel, ccb.address FROM ( SELECT c.id, c.parent_id as parentId, c.`name`, c.credit_code as creditCode, c.type, c.order_num as orderNum, cb.abbreviation, cb.clinic_number AS clinicNumber, cb.brandName, cb.tel, cb.address FROM company c LEFT JOIN ( SELECT cei.company_id, cei.abbreviation, cei.clinic_number, cei.tel, cei.address, ( SELECT GROUP_CONCAT( b.`name` ) FROM brand b WHERE FIND_IN_SET( b.id, cei.brand_ids )) AS brandName FROM clinic_ext_info cei ) cb ON c.id = cb.company_id ) ccb
and ccb.id = #{queryForm.id}
and ccb.name like CONCAT(CONCAT('%',#{queryForm.name}),'%')
and ccb.type in
#{item}
and ccb.clinicNumber = #{queryForm.clinicNumber}
and ccb.abbreviation like CONCAT(CONCAT('%',#{queryForm.abbreviation}),'%')
order by parentId, orderNum
